import assert from'node:assert/strict';
import{readFileSync}from'node:fs';
import{execFileSync}from'node:child_process';
import{createHash}from'node:crypto';
import{verifyKlink10GrammarRelease,readBeforeKlink10Grammar}from'./check-klink10-grammar-release-20261102.mjs';
const folder='docs/handwriting-20261102/short-screen/',roots=['app','components','hooks','data','lib','public','scripts','db','drizzle','.github','AGENTS.md','PUBLICATIE.md','VORMGEVING-VASTGEZET.md','docs/appearance-floor-20261031','docs/KLINK-DOCENTHANDLEIDING.md','vite.config.ts','next.config.ts','package.json','package-lock.json','wrangler.jsonc'],git=(...args)=>execFileSync('git',args,{maxBuffer:128e6}),sha=b=>createHash('sha256').update(b).digest('hex'),lines=b=>b.toString().trim().split('\n').filter(Boolean),sort=a=>a.sort((a,b)=>a.localeCompare(b));
export function verifyHandwritingShortScreenRelease(read=readFileSync){
 const next=verifyKlink10GrammarRelease(read),currentRead=read;read=file=>readBeforeKlink10Grammar(file,next,currentRead);
 const json=p=>JSON.parse(read(p)),r=json('docs/klink-owner-release-handwriting-short-screen-20261102.json');assert.equal(r.approvedBy,'Nico');assert.equal(r.ownerApproval,'standing-owner-approval');assert(r.publicationApproved&&r.existingAppearancePreserved&&r.progressPreserved&&r.onlyNewInkSizeBoundedByAvailableHeight);assert.equal(r.baselineSourceCommit,'8dd144b1f6ebebaa9a604df55bf5c0008f05ee07');git('merge-base','--is-ancestor',r.baselineSourceCommit,'HEAD');
 const changed=sort(lines(git('diff','--name-only',r.baselineSourceCommit,next.baselineSourceCommit,'--',...roots)));assert.deepEqual(changed,r.changedFiles);assert.deepEqual(changed,sort(['components/product/writing-board.css','scripts/check-handwriting-release-20261102.mjs','scripts/check-handwriting-short-screen-release-20261102.mjs','scripts/test-handwriting-layout-20261102.mjs','scripts/test-handwriting-short-screen-20261102.mjs','scripts/test-handwriting-short-screen-release-20261102.mjs']));assert.deepEqual(sort(Object.keys(r.files)),changed);for(const[p,h]of Object.entries({...r.files,...r.evidenceFiles}))assert.equal(sha(read(p)),h,p);
 const css='components/product/writing-board.css',oldCss=git('show',r.baselineSourceCommit+':'+css).toString();assert.equal(read(css).toString(),oldCss.replace('width: min(100%, 500px, 100vh);','width: min(100%, 500px, 100vh, calc((100cqh - 56px) * 1000 / 450));'),'Only the new handwriting SVG may change size; existing teacher defaults and all other styling stay exact');
 const layout='scripts/test-handwriting-layout-20261102.mjs';assert.equal(read(layout).toString(),git('show',r.baselineSourceCommit+':'+layout).toString().replace('geometry.box.height>100','geometry.box.height>=90'));
 const local=json(folder+'local/short-screen.json');assert.equal(local.checks.length,16);assert.deepEqual(local.errors,[]);assert(local.checks.every(c=>c.allFourCornersReachableByActualMouseWheel&&c.uniformScaleAndOriginalInkPreserved&&c.geometry.corners.every(Boolean)));const layouts=json(folder+'local/layout.json');assert.equal(layouts.checks.length,72);assert.deepEqual(layouts.errors,[]);assert(layouts.checks.every(c=>c.uniformScale&&c.originalInkGeometryPreserved&&c.noHorizontalOverflow&&c.noListeningControlsOverWriting));const v=json(folder+'verification.json');assert(v.beforeFailureReproduced&&v.localShortScreenPassed&&v.localLayoutsPassed&&v.normalSizeInkScreensUnchanged&&v.existingTeacherStyleByteExact&&v.noApplicationLogicOrMediaChanged&&v.lint&&v.types);assert.equal(v.physicalPhoneOrPenTested,false);assert.equal(v.humanListeningPerformed,false);
 const backup=json(folder+'backup.json');assert(backup.verified&&backup.fullReadback&&backup.zipIntegrity&&backup.driveId);assert.deepEqual(backup.files,r.files);assert.deepEqual(backup.evidenceFiles,r.evidenceFiles);return {...r,next};
}
export function readBeforeHandwritingShortScreen(file,r,read=readFileSync){return r.changedFiles.includes(file)?git('show',r.baselineSourceCommit+':'+file):readBeforeKlink10Grammar(file,r.next,read);}
